void ServerSheet::load()
{
    set_state(State::Loading);
    m_load_deadline.StartOnce(kLoadDeadlineMs);
    request_link([this](std::string url) {
        if (url.empty() || m_view == nullptr) {
            m_load_deadline.Stop();
            set_state(State::Failed);
            return;
        }
        m_view->LoadURL(wxString::FromUTF8(url));
    });
}

void ServerSheet::request_link(std::function<void(std::string)> use)
{
    const unsigned request = ++m_request;
    request_web_link(m_page, m_from, [this, alive = std::weak_ptr<bool>(m_alive), request, use = std::move(use)](std::string url) {
        if (!alive.expired() && !m_closing && request == m_request)
            use(std::move(url));
    });
}

void ServerSheet::open_in_browser()
{
    // A fresh link: the one the sheet opened has been used.
    request_link([this](std::string url) {
        if (url.empty()) {
            set_state(State::Failed);
            return;
        }
        wxLaunchDefaultBrowser(wxString::FromUTF8(url));
        close();
    });
}

void ServerSheet::set_state(State state)
{
    m_state = state;
    // One sentence per page, so the page's title never goes inside another.
    const bool billing = m_page == "billing";
    if (state == State::Loading)
        m_status_title->SetLabel(billing ? _L("Loading Billing and usage…") : _L("Loading Credits and plans…"));
    else if (state == State::Failed)
        m_status_title->SetLabel(billing ? _L("Couldn't load Billing and usage") : _L("Couldn't load Credits and plans"));
    m_status_detail->Show(state == State::Failed);
    m_retry->Show(state == State::Failed);
    if (m_view != nullptr)
        m_view->Show(state == State::Page);
    m_status->Show(state != State::Page);
    m_body->Layout();
}

void ServerSheet::on_navigating(wxWebViewEvent& event)
{
    if (!Agent::is_cloud_web_done(wxGetApp().app_config, event.GetURL().ToUTF8().data()))
        return;
    event.Veto();
    // Not from inside the web view's own callback: closing destroys it.
    CallAfter(reported("closing an account page", [this] { close(); }));
}

void ServerSheet::on_loaded(wxWebViewEvent& event)
{
    if (event.GetURL().empty() || event.GetURL() == "about:blank")
        return;
    m_load_deadline.Stop();
    set_state(State::Page);
}

void ServerSheet::on_error(wxWebViewEvent& event)
{
    // A new load, or the done address the sheet turned away, cancels the one
    // before it: not a failure.
    if (event.GetInt() == wxWEBVIEW_NAV_ERR_USER_CANCELLED || m_closing)
        return;
    m_load_deadline.Stop();
    set_state(State::Failed);
}

// A link goes to the person's browser: the sheet holds one page. A pop-up
// that reports back to the page is allowed, and the web view then asks for
// a window to put it in (on_new_window_features).
{
    event.Skip();
    // A page that comes late still replaces the problem.
    if (event.GetURL().empty() || event.GetURL() == "about:blank")
        return;
    m_load_deadline.Stop();
    hide_problem();
}

void PrinterWindow::on_error(wxWebViewEvent& event)
{
    event.Skip();
    // Try again, or a new address, cancels the load before it: not a failure.
    if (event.GetInt() == wxWEBVIEW_NAV_ERR_USER_CANCELLED)
        return;
    m_load_deadline.Stop();
    // The printer answered, but its secure connection could not be checked:
    // a certificate of its own, as most printers on a home network have, or
    // an https address on a printer that only speaks http, whose failed
    // handshake WebKit on macOS reports under wx's AUTH kind. A page behind a
    // password is no error here: WebKit shows the printer's own 401 page.
    const int  kind   = event.GetInt();
    const bool secure = kind == wxWEBVIEW_NAV_ERR_CERTIFICATE ||
                        (kind == wxWEBVIEW_NAV_ERR_AUTH && wxString::FromUTF8(m_url).Lower().StartsWith("https://"));
    show_problem(secure);
}

void PrinterWindow::show_problem(bool secure_connection)
{
    if (m_problem->IsShown())
        return;
    // A new label each time: wx's Wrap() keeps the first text it wrapped and
    // skips a width it has already wrapped at, so a reused one comes back
    // unwrapped, or with the old address.
    const wxString address = wxString::FromUTF8(m_address);
    auto*          detail  = new wxStaticText(m_problem, wxID_ANY, secure_connection ?
        // TRN %s is the printer's address without its scheme, such as 192.168.1.42:7125. Printer settings is the printer's settings window.
        wxString::Format(_L("The printer at %s answered, but JusPrin couldn't check its secure connection. If the printer's address starts with https://, change it to http:// in Printer settings, then try again."), address) :
        wxString::Format(_L("Nothing answered at %s. Check that the printer is turned on and on the same network as this computer, then try again."), address));
    m_problem_detail->GetContainingSizer()->Replace(m_problem_detail, detail);
    m_problem_detail->Destroy();
    m_problem_detail = detail;
    apply_appearance();
    m_problem_detail->Wrap(std::max(FromDIP(240), GetClientSize().GetWidth() / 2));
    m_view->Hide();
    m_problem->Show();
        .header("Accept", "application/json")
        .set_post_body(nlohmann::json{{"page", page}, {"from", from}}.dump())
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        .on_complete(reported("opening an account page", [finish](std::string body, unsigned status) {
            const nlohmann::json answer = nlohmann::json::parse(body, nullptr, false);
            std::string          url = status == 200 && answer.is_object() ? answer.value("url", std::string()) : std::string();
            if (url.empty())
                BOOST_LOG_TRIVIAL(warning) << "JusPrin page link answered " << status;
            finish(std::move(url));
        }))
        .on_error(reported("opening an account page", [finish](std::string, std::string error, unsigned status) {
            BOOST_LOG_TRIVIAL(warning) << "JusPrin page link failed: " << status << " " << error;
            finish({});
        }))
        .perform();

