void AgentHost::pump_conversation_title()
{
    const auto event = m_agent->poll();
    if (!event) return;
    if (event->kind == AgentEventKind::TextDelta) {
        m_title->text += event->text;
        if (m_title->text.size() <= 2048) return;
    } else if (event->kind == AgentEventKind::Completed && is_valid_utf8(m_title->text) &&
               m_persistence.document().rename_conversation(m_title->conversation_id, m_title->text, true)) {
        m_title.reset();
        m_persistence.flush();
        send_conversations();
        return;
    }
    // A failure the person can act on (an unexpected one throws from poll,
    // for the pump's report), or an answer that is no title: the chat stays
    // untitled and asks again after its next reply, whose own request meets
    // the same cause and says so.
    cancel_conversation_title();
}

void AgentHost::start_next_queued_reply()
{
    if (agent_busy() || m_queued_user_message_ids.empty())
        return;
    const std::string next = m_queued_user_message_ids.front();
    http.header("Accept", "application/json")
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        .on_progress([cancelled](Slic3r::Http::Progress, bool& cancel) { cancel = *cancelled; })
        .on_complete(reported("reading the account", [cancelled, finished](std::string body, unsigned status) {
            if (*cancelled)
                return;
            (*finished)(account_answer(status, body));
        }))
        .on_error(reported("reading the account", [cancelled, finished](std::string body, std::string, unsigned status) {
            if (!*cancelled)
                (*finished)(account_answer(status, body));
        }))
        .perform();
}

void fetch_account_box(const ProviderProfile& profile, const std::string& token, const std::string& url,
                       std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(std::optional<std::string>)> done)
{
    auto finished = std::make_shared<std::function<void(std::optional<std::string>)>>(std::move(done));
    auto http     = Slic3r::Http::get(url);
    if (!token.empty())
        http.header("Authorization", "Bearer " + token);
    for (const AgentHttpHeader& header : profile.headers)
        http.header(header.name, header.value);
    http.header("Accept", "text/html")
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        .on_progress([cancelled](Slic3r::Http::Progress, bool& cancel) { cancel = *cancelled; })
