TEST_CASE("OpenAI errors are safe and actionable", "[agent][openai][errors]")
{
    auto transport = std::make_unique<FakeTransport>();
    FakeTransport* fake = transport.get();
    OpenAIResponsesAgent agent({"key"}, std::move(transport));
    REQUIRE(agent.start(request_fixture()));
    fake->error(429, "sensitive upstream body");
    const auto event = poll_until(agent, AgentEventKind::Failed);
    REQUIRE(event);
    REQUIRE(event->error);
    CHECK(event->error->code == "rate_limited");
    CHECK(event->error->retryable);
    CHECK(event->error->message.find("sensitive") == std::string::npos);

    REQUIRE(agent.start(request_fixture()));
    fake->data("data: not-json\n\n");
    CHECK_THROWS_WITH(poll_until(agent, AgentEventKind::Failed), Catch::Matchers::ContainsSubstring("sent an event that is not JSON: not-json"));

    REQUIRE(agent.start(request_fixture()));
    agent.cancel();
    CHECK(fake->cancelled);
    CHECK_FALSE(agent.busy());
}

namespace {

// A Responses agent for a provider row, its fake transport, and its first
// failure. A key check sends the same request, so it ends the same way.
struct Responses
{
    explicit Responses(const char* provider)
    {
        auto transport = std::make_unique<FakeTransport>();
        fake           = transport.get();
        agent          = make_provider_agent(*profile_for(provider), "sk-secret", "", "", std::move(transport));
        REQUIRE(agent->start(request_fixture()));
    }
    std::optional<AgentError> failure()
    {
        for (int i = 0; i < 20; ++i)
