// What the app log receives while it lives.
struct CapturedLog
{
    CapturedLog()
    {
        auto backend = boost::make_shared<boost::log::sinks::text_ostream_backend>();
        backend->add_stream(boost::shared_ptr<std::ostream>(&text, boost::null_deleter()));
        sink = boost::make_shared<boost::log::sinks::synchronous_sink<boost::log::sinks::text_ostream_backend>>(backend);
        sink->set_formatter(boost::log::expressions::stream << boost::log::expressions::smessage);
        boost::log::core::get()->add_sink(sink);
    }
    ~CapturedLog() { boost::log::core::get()->remove_sink(sink); }
    std::string lines()
    {
        sink->flush();
        return text.str();
    }
    std::ostringstream text;
    boost::shared_ptr<boost::log::sinks::synchronous_sink<boost::log::sinks::text_ostream_backend>> sink;
};

