{
    // A new load, or the done address the sheet turned away, cancels the one
    // before it: not a failure.
    if (event.GetInt() == wxWEBVIEW_NAV_ERR_USER_CANCELLED || m_closing)
        return;
    m_load_deadline.Stop();
    set_state(State::Failed);
}

