void AgentHost::start_mcp(const std::string& discovery_path)
{
#include "McpRuntime.hpp"
#include <boost/log/trivial.hpp>

namespace Slic3r::GUI::JusPrin::Mcp {
using nlohmann::json;

McpRuntime::McpRuntime(Workspace::IWorkspace& workspace, Agent::ToolExecutionCoordinator& coordinator,
                       std::filesystem::path discovery_path, ServerOptions options)
    : m_workspace(workspace), m_coordinator(coordinator), m_server(options),
      m_discovery_path(std::move(discovery_path)), m_discovery(write_discovery(m_discovery_path, m_server.url()))
{
    m_subscription = m_coordinator.subscribe([this](const Agent::ToolActivity& activity) { on_activity(activity); });
}

McpRuntime::~McpRuntime()
{
    m_server.stop(); // no worker can queue another request after this point
    detach_calls();
    try {
        remove_discovery(m_discovery_path, m_discovery.instance_id);
    } catch (const std::filesystem::filesystem_error& error) {
        // Cleanup can lose access after startup. The socket is already closed;
        // retaining a stale record is safe because readers must probe liveness.
        BOOST_LOG_TRIVIAL(warning) << "MCP discovery cleanup left a stale file: " << error.what();
    }
}

void McpRuntime::detach_calls()
{
    // Project replacement may clear the coordinator's records. Finish waiters
    // the app's own.
    std::string page_event;
    // Where the app found its own failure (ThrowStack.hpp failure_stack()),
    // innermost first; empty when it was not taken.
    std::vector<void*> stack;
};

// The AppConfig key of "report errors automatically", off until the person
// turns it on in the dialog or in Preferences › Updates.
inline constexpr const char* kReportErrorsKey = "jusprin_report_errors_automatically";

// Reports one unexpected error: sends it at once when automatic reports are
// on, otherwise opens the dialog after the current event, over the window in
// front. Only top handlers call this.
void report_unexpected_error(std::string doing, std::string error, std::string where = {}, std::string page_event = {});

// Reports a tool call that failed in the app's own work, whose error already
// went to the AI model, or a start report the server answered with a fault
// (LaunchReport): sent only when automatic reports are on, and no dialog
// opens. Any thread.
void report_if_automatic(std::string doing, std::string error);
